  gorsel: `<svg viewBox="0 0 560 209" role="img" aria-label="BİSKÜVİ PAKETİ ETİKETİ"><rect x="90" y="10" width="380" height="189" rx="12" fill="none" stroke="currentColor" stroke-width="2"/><rect x="98" y="18" width="364" height="36" rx="8" fill="var(--dolgu)" stroke="var(--vurgu)" stroke-width="2"/><text x="280" y="42" font-size="17" text-anchor="middle" font-weight="bold" fill="var(--vurgu)">BİSKÜVİ PAKETİ ETİKETİ</text><text x="106" y="82" font-size="15" fill="currentColor">Pakette 4 porsiyon vardır.</text><text x="106" y="105" font-size="15" fill="currentColor">1 porsiyon: 30 g</text><text x="106" y="128" font-size="15" fill="currentColor">1 porsiyonda enerji: 120 kcal</text><text x="106" y="151" font-size="15" fill="currentColor">1 porsiyonda yağ: 5 g</text><text x="106" y="174" font-size="15" fill="currentColor">1 porsiyonda şeker: 8 g</text></svg>`,
