  gorsel: `<svg viewBox="0 0 560 300" role="img" aria-label="Grafik: Akşamları yapılan etkinlik"><text x="10" y="24" font-size="16" font-weight="bold" fill="currentColor">Grafik: Akşamları yapılan etkinlik</text><path d="M 280 168 L 280 76 A 92 92 0 1 1 251.6 255.5 Z" fill="var(--dolgu)" fill-opacity="1" stroke="currentColor" stroke-width="2"/><path d="M 280 168 L 251.6 255.5 A 92 92 0 0 1 188 168 Z" fill="var(--vurgu)" fill-opacity="1" stroke="currentColor" stroke-width="2"/><path d="M 280 168 L 188 168 A 92 92 0 0 1 225.9 93.6 Z" fill="var(--vurgu2)" fill-opacity="1" stroke="currentColor" stroke-width="2"/><path d="M 280 168 L 225.9 93.6 A 92 92 0 0 1 280 76 Z" fill="currentColor" fill-opacity="0.25" stroke="currentColor" stroke-width="2"/><text x="382.7" y="189.3" font-size="14" text-anchor="start" font-weight="bold" fill="currentColor">Yürüyüş %55</text><text x="195.9" y="243.1" font-size="14" text-anchor="end" font-weight="bold" fill="currentColor">Bahçede oturma %20</text><text x="187.3" y="125.8" font-size="14" text-anchor="end" font-weight="bold" fill="currentColor">Spor %15</text><text x="247.9" y="74.1" font-size="14" text-anchor="end" font-weight="bold" fill="currentColor">Diğer %10</text></svg>`,
